-- Migration 063: Analytics tables for comprehensive user engagement tracking

-- 1. Page views — frontend sends beacon on each SPA navigation
CREATE TABLE IF NOT EXISTS page_views (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id     INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    path        TEXT NOT NULL,
    referrer    TEXT,
    session_id  TEXT NOT NULL,
    duration_ms INTEGER,
    created_at  DATETIME NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_page_views_user_id ON page_views(user_id);
CREATE INDEX IF NOT EXISTS idx_page_views_created_at ON page_views(created_at);
CREATE INDEX IF NOT EXISTS idx_page_views_session ON page_views(session_id);

-- 2. API request log — middleware logs every authenticated API request
CREATE TABLE IF NOT EXISTS api_request_log (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id     INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    api_key_id  INTEGER REFERENCES api_keys(id) ON DELETE SET NULL,
    method      TEXT NOT NULL,
    path        TEXT NOT NULL,
    status_code INTEGER NOT NULL,
    duration_ms INTEGER NOT NULL,
    agent_name  TEXT,
    ip_address  TEXT,
    created_at  DATETIME NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_api_request_log_user_id ON api_request_log(user_id);
CREATE INDEX IF NOT EXISTS idx_api_request_log_api_key ON api_request_log(api_key_id);
CREATE INDEX IF NOT EXISTS idx_api_request_log_created ON api_request_log(created_at);
CREATE INDEX IF NOT EXISTS idx_api_request_log_path ON api_request_log(path);

-- 3. User sessions — aggregated session data for time-on-site tracking
CREATE TABLE IF NOT EXISTS user_sessions (
    id                INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id           INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    session_id        TEXT NOT NULL UNIQUE,
    started_at        DATETIME NOT NULL DEFAULT (datetime('now')),
    last_seen_at      DATETIME NOT NULL DEFAULT (datetime('now')),
    page_count        INTEGER NOT NULL DEFAULT 1,
    total_duration_ms INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_user_sessions_user_id ON user_sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_user_sessions_started ON user_sessions(started_at);

package schema

import (
	"time"

	"entgo.io/ent"
	"entgo.io/ent/schema/edge"
	"entgo.io/ent/schema/field"
	"entgo.io/ent/schema/index"
)

// Sprint holds the schema definition for the Sprint entity.
type Sprint struct {
	ent.Schema
}

// Fields of the Sprint.
func (Sprint) Fields() []ent.Field {
	return []ent.Field{
		field.Int64("id"),
		field.Int64("user_id"),
		field.Int64("team_id").Optional().Nillable(),
		field.String("name").NotEmpty(),
		field.String("goal").Optional().Nillable(),
		field.Time("start_date").Optional().Nillable(),
		field.Time("end_date").Optional().Nillable(),
		field.String("status").Default("planned"),
		field.Time("created_at").Default(time.Now).Immutable(),
		field.Time("updated_at").Default(time.Now).UpdateDefault(time.Now),
	}
}

// Edges of the Sprint.
func (Sprint) Edges() []ent.Edge {
	return []ent.Edge{
		edge.From("user", User.Type).Ref("sprints").Unique().Required().Field("user_id"),
		edge.From("team", Team.Type).Ref("sprints").Unique().Field("team_id"),
		edge.To("tasks", Task.Type),
	}
}

// Indexes of the Sprint.
func (Sprint) Indexes() []ent.Index {
	return []ent.Index{
		index.Fields("user_id"),
		index.Fields("team_id"),
		index.Fields("status"),
	}
}

