    method: "POST",
    body: JSON.stringify(data),
  });
}

async deleteDependency(dependencyId: string): Promise<void> {
  await this.request(`/api/task-dependencies/${encodeURIComponent(dependencyId)}`, { method: "DELETE" });
}

